func:
// SIMULATOR - stands in for a real protocol input node (MQTT/Modbus/OPC-UA).
// Swap this node for that input node in production; every downstream node
// only cares that msg.payload matches this raw shape:
//   { machine_id, ts, temp_raw, vibration_samples[], pressure_raw, cycle_pulse_count }
const machines = ['press-01', 'press-02', 'cnc-04'];
const id = machines[Math.floor(Math.random() * machines.length)];

// context-tracked cycle pulse counter per machine (simulates a PLC counter)
const counters = context.get('cycleCounters') || {};
counters[id] = (counters[id] || 0) + (Math.random() > 0.3 ? 1 : 0);
context.set('cycleCounters', counters);

msg.payload = {
    machine_id: id,
    ts: Date.now(),
    // raw ADC counts, 0-4095, needs scaling downstream
    temp_raw: 1200 + Math.round(Math.random() * 300),
    // raw accelerometer samples for an RMS calc downstream
    vibration_samples: Array.from({ length: 20 }, () => (Math.random() - 0.5) * (Math.random() > 0.95 ? 8 : 2)),
    pressure_raw: 2000 + Math.round(Math.random() * 500),
    cycle_pulse_count: counters[id]
};
return msg;

// Convert raw sensor units into calibrated engineering units.
// Replace the scale/offset constants with your instrumentation's real
// calibration values (from the sensor datasheet or a calibration cert).
const p = msg.payload;

// Example: 12-bit ADC (0-4095) mapped to 0-150C via a linear scale
const TEMP_SCALE = 150 / 4095;
const temperature_c = +(p.temp_raw * TEMP_SCALE).toFixed(2);

// Vibration RMS from raw accelerometer samples (g)
const samples = p.vibration_samples || [];
const rms = samples.length
    ? Math.sqrt(samples.reduce((sum, v) => sum + v * v, 0) / samples.length)
    : 0;
const vibration_rms_g = +rms.toFixed(3);

// Example: pressure transducer, 0-4095 raw -> 0-250 psi
const PRESSURE_SCALE = 250 / 4095;
const pressure_psi = +(p.pressure_raw * PRESSURE_SCALE).toFixed(2);

msg.payload = {
    machine_id: p.machine_id,
    ts: p.ts,
    temperature_c,
    vibration_rms_g,
    pressure_psi,
    cycle_pulse_count: p.cycle_pulse_count
};
return msg;

// Keeps per-machine rolling history in flow context so we can compute
// trends and machine state without a database round-trip on every message.
const p = msg.payload;
const key = p.machine_id;

const history = flow.get('history') || {};
const h = history[key] || {
    temps: [], lastCycleCount: p.cycle_pulse_count, cycleTotal: 0,
    lastRunState: null, lastStateChangeTs: p.ts
};

// Rolling average temperature over the last 20 readings
h.temps.push(p.temperature_c);
if (h.temps.length > 20) h.temps.shift();
const temp_rolling_avg_c = +(h.temps.reduce((a, b) => a + b, 0) / h.temps.length).toFixed(2);

// Cycle delta since last reading (handles PLC counter reset to 0)
const cycleDelta = p.cycle_pulse_count >= h.lastCycleCount
    ? p.cycle_pulse_count - h.lastCycleCount
    : p.cycle_pulse_count;
h.cycleTotal += cycleDelta;
h.lastCycleCount = p.cycle_pulse_count;

// Running/idle state from vibration - tune this threshold per machine type.
const runState = p.vibration_rms_g > 0.35 ? 'running' : 'idle';
if (runState !== h.lastRunState) {
    h.lastStateChangeTs = p.ts;
    h.lastRunState = runState;
}
const seconds_in_state = Math.round((p.ts - h.lastStateChangeTs) / 1000);

history[key] = h;
flow.set('history', history);

msg.payload = {
    ...p,
    temp_rolling_avg_c,
    cycle_total: h.cycleTotal,
    run_state: runState,
    seconds_in_state
};
return msg;

// Composite/synthetic tags that don't come off any single sensor - the
// kind of thing a plant manager actually wants on a dashboard.
const p = msg.payload;

// Anomaly score: how far current temp is from its own rolling average,
// normalized. >1 is 'worth a look' - tune per equipment.
const deviation = Math.abs(p.temperature_c - p.temp_rolling_avg_c);
const anomaly_score = +(deviation / 5).toFixed(2);

// Simple composite health score (0-100): penalize high vibration,
// temperature deviation, and prolonged idle equally for a first pass -
// replace with a client-specific weighting once you have failure history.
let health_score = 100;
health_score -= Math.min(40, p.vibration_rms_g * 40);
health_score -= Math.min(40, anomaly_score * 20);
if (p.run_state === 'idle' && p.seconds_in_state > 300) health_score -= 10;
health_score = Math.max(0, Math.round(health_score));

msg.payload = {
    ...p,
    anomaly_score,
    health_score,
    alert: anomaly_score > 1.5 || p.vibration_rms_g > 0.6
};
return msg;

// Shapes the enriched reading into the format node-red-contrib-influxdb's
// "InfluxDB out" node (API v2) expects for a single point:
//   msg.payload = [ fieldsObject, tagsObject ]
// Tags = low-cardinality, indexed, used for filtering/grouping (strings only).
// Fields = the actual measured/derived values. A field literally named
// "time" is handled specially by the node and becomes the point's
// timestamp - see node_modules/node-red-contrib-influxdb's addFieldToPoint().
// The measurement name itself ("machine_metrics") is set on the
// "InfluxDB out" node's Measurement field rather than here, since it's
// constant for this flow.
const p = msg.payload;

const fields = {
    time: new Date(p.ts),
    temperature_c: p.temperature_c,
    temp_rolling_avg_c: p.temp_rolling_avg_c,
    vibration_rms_g: p.vibration_rms_g,
    pressure_psi: p.pressure_psi,
    cycle_total: p.cycle_total,
    seconds_in_state: p.seconds_in_state,
    anomaly_score: p.anomaly_score,
    health_score: p.health_score,
    alert: p.alert
};

const tags = {
    machine_id: p.machine_id,
    run_state: p.run_state
};

msg.payload = [fields, tags];
return msg;
